package com.smarthospital.controller;
import com.smarthospital.util.*; import javax.servlet.*; import javax.servlet.http.*; import javax.servlet.annotation.*; import java.io.*; import java.sql.*;
@WebServlet("/login") public class LoginServlet extends HttpServlet {
 protected void doPost(HttpServletRequest req,HttpServletResponse resp)throws IOException,ServletException{String u=req.getParameter("username"),p=req.getParameter("password");try(Connection c=DB.getConnection();PreparedStatement q=c.prepareStatement("SELECT user_id,username,password_hash,role FROM users WHERE username=? AND status='ACTIVE'")){q.setString(1,u);ResultSet r=q.executeQuery();if(r.next()&&PasswordUtil.verify(p,r.getString(3))){if("on".equals(req.getParameter("remember"))){Cookie ck=new Cookie("remember_username",u);ck.setMaxAge(60*60*24*30);ck.setHttpOnly(true);ck.setPath(req.getContextPath().isEmpty()?"/":req.getContextPath());resp.addCookie(ck);}HttpSession old=req.getSession(false);if(old!=null)old.invalidate();HttpSession s=req.getSession(true);s.setAttribute("user",new com.smarthospital.model.User(r.getInt(1),r.getString(2),r.getString(4)));Audit.log(r.getInt(1),"LOGIN","Successful login");resp.sendRedirect(req.getContextPath()+"/dashboard");}else{req.setAttribute("error","Invalid username or password.");req.getRequestDispatcher("/login.jsp").forward(req,resp);}}catch(Exception e){req.setAttribute("error","Database connection failed. Check MySQL configuration.");req.getRequestDispatcher("/login.jsp").forward(req,resp);}}
}
